persuasion_principles:
{
    "Reciprocity": {"Explanation": "The email offers access to a four-week online workshop with exclusive content and expert advice, which can be seen as a form of reciprocity, as the reader might feel they need to reciprocate by participating in the workshop."},
    "Scarcity": {"Explanation": "The email implies scarcity by mentioning 'only four weeks away' until Easter and 'our workshop begins February 25!', creating a sense of urgency to act quickly."},
    "Authority": {"Explanation": "The email mentions 'experts' guiding the workshop and 'Martha Stewart Living', which lends authority and credibility to the offer."},
