    "Authority": {"Explanation": "The email does not explicitly reference any authority or credible source to lend legitimacy to the request, so this principle is not present."},
    "Commitment/Consistency": {"Explanation": "The email references prior actions by thanking those who have already completed the survey, aiming to encourage further commitment from others by leveraging their past behavior."},
    "Liking": {"Explanation": "The email uses personalization and familiarity by addressing recipients as 'those of you' and thanking them for their previous actions, which helps build rapport and liking."},
    "Social proof": {"Explanation": "The email mentions that 'nearly 27% of all ETS employees have completed the pulse survey', providing social proof that others have participated, thus encouraging more participation from the remaining employees."}
}

